package it.frociart.app;
import java.io.*;import java.nio.*;import java.nio.channels.*;import java.nio.charset.*;import java.nio.file.*;import java.security.*;import java.util.*;
/** Bounded private library. Each model owns one directory; archive/restore is a single atomic rename. */
final class FlowTemplateStore {
    static final int MAX_ENTRIES=32,MAX_ARCHIVE=32,MAX_TOTAL_BYTES=8388608,MAX_DRAFT_CHARACTERS=524288;
    static final class Entry {
        final String id,raw,draft,fingerprint,problem;final FlowCodeTemplate definition;final boolean archived;
        Entry(String i,String r,String d,String f,FlowCodeTemplate t,String p,boolean a){id=i;raw=r;draft=d;fingerprint=f;definition=t;problem=p;archived=a;}
        String name(){return definition==null?problem!=null?"Modello da recuperare":raw==null?"Bozza di modello":"Modello da recuperare":definition.name;}
    }
    final Path root,archive;
    FlowTemplateStore(File root){this.root=root.toPath().toAbsolutePath().normalize();archive=this.root.resolve("archive");}
    static String newId(){return UUID.randomUUID().toString().replace("-","");}
    Path folder(String id,boolean archived){if(id==null||!id.matches("^[a-f0-9]{32}$"))throw new IllegalArgumentException("Identificativo del modello non valido.");return(archived?archive:root).resolve(id);}
    static String fingerprint(byte[] bytes){try{StringBuilder b=new StringBuilder();for(byte n:MessageDigest.getInstance("SHA-256").digest(bytes))b.append(String.format(Locale.ROOT,"%02x",n&255));return b.toString();}catch(NoSuchAlgorithmException ex){throw new IllegalStateException(ex);}}
    static boolean emptyFolder(Path path)throws IOException{try(DirectoryStream<Path> files=Files.newDirectoryStream(path)){return !files.iterator().hasNext();}}
    static void plainFolder(Path path)throws IOException{if(Files.isSymbolicLink(path))throw new IOException("La cartella del modello non è una cartella locale normale.");}
    static byte[] bytes(Path path,int limit)throws IOException{try(InputStream input=Files.newInputStream(path);ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int count;while((count=input.read(buffer))!=-1){if(output.size()+count>limit)throw new IOException("Il file del modello supera il limite di dimensione.");output.write(buffer,0,count);}return output.toByteArray();}}
    static String decode(byte[] bytes)throws IOException{try{return FlowCodeTemplate.decode(bytes);}catch(IllegalArgumentException error){throw new IOException(error.getMessage());}}
    static String readImport(File path)throws IOException{return decode(bytes(path.toPath(),FlowCodeTemplate.MAX_BYTES));}
    Entry load(String id)throws IOException{return load(id,false);}Entry load(String id,boolean archived)throws IOException{Path folder=folder(id,archived);plainFolder(folder);String raw=null,draft=null,fingerprint=null,problem=null;FlowCodeTemplate definition=null;Path file=folder.resolve("definition.frotemplate");if(Files.exists(file))try{if(Files.isSymbolicLink(file))throw new IOException("Il modello contiene un collegamento a un altro file.");byte[] bytes=bytes(file,FlowCodeTemplate.MAX_BYTES);fingerprint=fingerprint(bytes);raw=decode(bytes);definition=FlowCodeTemplate.parse(raw);}catch(IOException|IllegalArgumentException ex){problem="Modello da recuperare: "+ex.getMessage();}
        file=folder.resolve("draft.txt");if(Files.exists(file))try{if(Files.isSymbolicLink(file))throw new IOException("La bozza contiene un collegamento a un altro file.");draft=decode(bytes(file,FlowCodeTemplate.MAX_BYTES));if(draft.length()>MAX_DRAFT_CHARACTERS)throw new IOException("Bozza troppo lunga.");}catch(IOException|IllegalArgumentException ex){problem=(problem==null?"":problem+"\n")+"Bozza da recuperare: "+ex.getMessage();}return new Entry(id,raw,draft,fingerprint,definition,problem,archived);
    }
    List<Entry> entries()throws IOException{return entries(false);}List<Entry> entries(boolean archived)throws IOException{Path parent=archived?archive:root;List<Entry> result=new ArrayList<>();if(!Files.isDirectory(parent))return result;plainFolder(parent);try(DirectoryStream<Path> directories=Files.newDirectoryStream(parent)){for(Path folder:directories){String id=folder.getFileName().toString();if(!Files.isDirectory(folder)||!id.matches("^[a-f0-9]{32}$"))continue;try{plainFolder(folder);if(emptyFolder(folder))continue;result.add(load(id,archived));}catch(IOException ex){result.add(new Entry(id,null,null,null,null,ex.getMessage(),archived));}}}Collections.sort(result,(a,b)->{int n=a.name().compareToIgnoreCase(b.name());return n!=0?n:a.id.compareTo(b.id);});return Collections.unmodifiableList(result);}
    static final class Locked implements AutoCloseable {final FileChannel channel;final FileLock lock;Locked(Path root)throws IOException{Files.createDirectories(root);plainFolder(root);channel=FileChannel.open(root.resolve(".lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);FileLock acquired;try{acquired=channel.tryLock();if(acquired==null)throw new IOException("L’archivio dei modelli è occupato. Riprova.");}catch(IOException|OverlappingFileLockException ex){channel.close();throw new IOException("L’archivio dei modelli è occupato. Riprova.",ex);}lock=acquired;}public void close()throws IOException{try{lock.release();}finally{channel.close();}}}
    void capacity(String id,int added,Path replaced)throws IOException{int count=0;long total=0;try(DirectoryStream<Path> directories=Files.newDirectoryStream(root)){for(Path folder:directories){String key=folder.getFileName().toString();if(!Files.isDirectory(folder)||!key.matches("^[a-f0-9]{32}$"))continue;plainFolder(folder);if(emptyFolder(folder))continue;count++;for(String name:new String[]{"definition.frotemplate","draft.txt"}){Path file=folder.resolve(name);if(Files.exists(file)&&!file.equals(replaced))total+=Files.size(file);}}}if((!Files.isDirectory(folder(id,false))||emptyFolder(folder(id,false)))&&count>=MAX_ENTRIES)throw new IOException("Hai già 32 modelli. Esporta o sposta nel cestino quelli che non usi.");if(total+added>MAX_TOTAL_BYTES)throw new IOException("L’archivio dei modelli supera 8 MiB. Esporta o sposta nel cestino quelli che non usi.");}
    static byte[] encode(String text,boolean draft){if(text==null||text.length()>(draft?MAX_DRAFT_CHARACTERS:FlowCodeTemplate.MAX_DEFINITION_CHARACTERS))throw new IllegalArgumentException("Testo del modello troppo lungo.");byte[] bytes;try{ByteBuffer buffer=StandardCharsets.UTF_8.newEncoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).encode(CharBuffer.wrap(text));bytes=new byte[buffer.remaining()];buffer.get(bytes);}catch(CharacterCodingException ex){throw new IllegalArgumentException("Il modello contiene un carattere Unicode incompleto.",ex);}if(bytes.length>FlowCodeTemplate.MAX_BYTES)throw new IllegalArgumentException("Il modello supera 1 MiB.");return bytes;}
    static void atomic(Path path,byte[] bytes)throws IOException{Path temporary=path.getParent().resolve(".pending-"+newId());try{try(FileChannel channel=FileChannel.open(temporary,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){ByteBuffer buffer=ByteBuffer.wrap(bytes);while(buffer.hasRemaining())channel.write(buffer);channel.force(true);}Files.move(temporary,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temporary);}}
    Entry save(String id,String text,String expectedFingerprint)throws IOException{FlowCodeTemplate definition=FlowCodeTemplate.parse(text);byte[] bytes=encode(definition.text,false);try(Locked guard=new Locked(root)){Path folder=folder(id,false);plainFolder(folder);Entry current=load(id);if(Files.exists(folder.resolve("definition.frotemplate"))&&current.fingerprint==null)throw new IOException("Il modello salvato non è leggibile. Conserva il file e salva una copia con un altro nome.");if(!Objects.equals(current.fingerprint,expectedFingerprint))throw new IOException("Il modello è cambiato. Riaprilo oppure salva una copia.");for(Entry entry:entries())if(!entry.id.equals(id)&&entry.definition!=null&&entry.definition.name.equalsIgnoreCase(definition.name))throw new IOException("Esiste già un modello con questo nome. Scegli un nome diverso.");Path file=folder.resolve("definition.frotemplate");capacity(id,bytes.length,file);Files.createDirectories(folder);atomic(file,bytes);return load(id);}}
    void saveDraft(String id,String text)throws IOException{byte[] bytes=encode(text,true);try(Locked guard=new Locked(root)){Path folder=folder(id,false);plainFolder(folder);Path file=folder.resolve("draft.txt");capacity(id,bytes.length,file);Files.createDirectories(folder);atomic(file,bytes);}}
    boolean clearDraft(String id,String expectedText)throws IOException{try(Locked guard=new Locked(root)){Path folder=folder(id,false);plainFolder(folder);Path file=folder.resolve("draft.txt");if(!Files.exists(file))return true;String actual=readImport(file.toFile());if(!Objects.equals(actual,expectedText))return false;Files.delete(file);boolean empty;try(DirectoryStream<Path> items=Files.newDirectoryStream(folder)){empty=!items.iterator().hasNext();}if(empty)Files.delete(folder);return true;}}
    void archive(String id,String expectedFingerprint)throws IOException{try(Locked guard=new Locked(root)){Path source=folder(id,false);plainFolder(source);if(!Files.isDirectory(source))throw new IOException("Il modello non è più disponibile.");Entry entry=load(id);if(!Objects.equals(entry.fingerprint,expectedFingerprint))throw new IOException("Il modello è cambiato. Riaprilo prima di spostarlo nel cestino.");knownFiles(source);Files.createDirectories(archive);plainFolder(archive);List<Entry> old=entries(true);long size=0;for(Entry e:old)size+=folderBytes(folder(e.id,true));if(old.size()>=MAX_ARCHIVE||size+folderBytes(source)>MAX_TOTAL_BYTES)throw new IOException("Il cestino dei modelli è pieno. Ripristina o elimina definitivamente alcuni modelli.");Files.move(source,folder(id,true),StandardCopyOption.ATOMIC_MOVE);}}
    void restore(String id)throws IOException{try(Locked guard=new Locked(root)){Path source=folder(id,true),destination=folder(id,false);plainFolder(archive);plainFolder(source);knownFiles(source);if(Files.exists(destination))throw new IOException("Esiste già un modello con lo stesso identificativo.");Entry entry=load(id,true);if(entry.definition!=null)for(Entry e:entries())if(e.definition!=null&&e.definition.name.equalsIgnoreCase(entry.definition.name))throw new IOException("Esiste già un modello con questo nome. Rinomina quello presente prima di ripristinarlo.");capacity(id,(int)folderBytes(source),null);Files.move(source,destination,StandardCopyOption.ATOMIC_MOVE);}}
    void deleteArchived(String id)throws IOException{try(Locked guard=new Locked(root)){Path folder=folder(id,true);plainFolder(archive);plainFolder(folder);knownFiles(folder);try(DirectoryStream<Path> files=Files.newDirectoryStream(folder)){for(Path file:files)Files.delete(file);}Files.delete(folder);}}
    static long folderBytes(Path folder)throws IOException{knownFiles(folder);long size=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(folder)){for(Path file:files)size+=Files.size(file);}if(size>MAX_TOTAL_BYTES)throw new IOException("La cartella del modello supera 8 MiB. Il contenuto è stato conservato.");return size;}
    static void knownFiles(Path folder)throws IOException{if(!Files.isDirectory(folder))throw new IOException("Il modello non è più disponibile.");try(DirectoryStream<Path> files=Files.newDirectoryStream(folder)){for(Path file:files){String name=file.getFileName().toString();if(Files.isDirectory(file)||!name.equals("definition.frotemplate")&&!name.equals("draft.txt"))throw new IOException("La cartella contiene file non riconosciuti: il contenuto è stato conservato.");if(Files.isSymbolicLink(file))throw new IOException("Il modello contiene un collegamento a un altro file.");}}}
    static void export(File path,FlowCodeTemplate definition)throws IOException{if(definition==null)throw new IllegalArgumentException("definition");atomic(path.toPath().toAbsolutePath().normalize(),encode(definition.exportText(),false));}
}
